package org.rabochaya.maptests;
import android.app.*;import android.content.*;import android.accessibilityservice.AccessibilityServiceInfo;import android.view.*;import android.widget.*;import java.util.*;import org.w3c.dom.Element;
/** Fresh synthetic projects only. Rotation must destroy the original Activity. */
final class ManagerRotationChecks {
 final MapAndroidChecks m;final ManagerVisualChecks v;
 ManagerRotationChecks(MapAndroidChecks checks){m=checks;v=new ManagerVisualChecks(m);}
 static final String XML="<kml xmlns='http://www.opengis.net/kml/2.2'><Document><Style id='style'><IconStyle><color>ff00ff00</color></IconStyle></Style><Folder id='folder'><name>QA_ROTATE_FOLDER</name><Placemark id='nested'><name>QA_ROTATE_NESTED</name><description>Nested note</description><Point><coordinates>11,21,31</coordinates></Point></Placemark></Folder><Placemark id='point'><name>QA_ROTATE_POINT</name><description>Original note</description><styleUrl>#style</styleUrl><TimeStamp><when>2026-10-30</when></TimeStamp><Point><coordinates>10,20,30</coordinates></Point></Placemark><Placemark id='other'><name>QA_ROTATE_OTHER</name><Point><coordinates>12,22,32</coordinates></Point></Placemark></Document></kml>";
 Object parse(byte[] xml)throws Exception{return m.codec.getMethod("parse",byte[].class).invoke(null,(Object)xml);}
 byte[] xml(Object doc)throws Exception{return (byte[])m.call(doc,"xml",new Class[]{});}
 Object load(Object store,long id)throws Exception{return m.call(store,"load",new Class[]{long.class},id);}
 void sameAssets(Object doc,Map<String,byte[]> before)throws Exception{Map<String,byte[]> actual=m.assets(doc);m.check(actual.keySet().equals(before.keySet()),"attachment names retained");for(String key:before.keySet())m.check(Arrays.equals(before.get(key),actual.get(key)),"attachment bytes retained: "+key);}
 boolean editorMatches(String text){boolean[] result={false};m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);result[0]=fields.size()==1&&text.contentEquals(fields.get(0).getText())&&fields.get(0).getSelectionStart()==3&&fields.get(0).getSelectionEnd()==8;});return result[0];}
 boolean saveEnabled(){boolean[] result={false};m.runOnMainSync(()->{View save=v.button(m.activeDialogRoot(),"Сохранить");result[0]=save!=null&&save.isEnabled();});return result[0];}
 void rotate(int direction,String text,String scene)throws Exception{Activity old=m.activity;v.rotate(direction);m.waitForIdleSync();Thread.sleep(600);m.check(m.activity!=old&&old.isDestroyed(),"actual Activity replacement: "+scene);boolean restored=editorMatches(text);if(!restored)v.snapshot(scene,false);m.check(restored,"exact unsaved text and selection 3..8 restored: "+scene);v.keyboard();v.snapshot(scene,true);}
 void externalChange(Object store,long id,boolean shift)throws Exception{Object newer=load(store,id);Element root=(Element)m.call(newer,"root",new Class[]{});if(shift){Element point=m.element(newer,"point"),other=m.element(newer,"other");other.getParentNode().insertBefore(other,point);}else m.element(newer,"point").setAttribute("external-update","keep");m.staticCall("ProjectWrites","savePreservingAssets",new Class[]{m.storeClass,long.class,m.codec},store,id,newer);}
 void scenario(Object store,String kind,String outcome)throws Exception{
  Object doc=parse(XML.getBytes("UTF-8"));for(String target:new String[]{"point","nested"})m.staticCall("MediaLinks","add",new Class[]{m.codec,Element.class,String.class,String.class,byte[].class},doc,m.element(doc,target),target+".jpg","image/jpeg",new byte[]{8,6,4,2});long id=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_ROTATION_"+kind+"_"+outcome);
  try{
   doc=load(store,id);byte[] before=xml(doc);String token=m.treeToken(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));String key=kind.equals("name")?"1":"0/0",operation=kind.equals("name")?"rename":"description";String text=kind.equals("name")?"QA_ROTATE_Новое имя 😀":"QA_ROTATE_Описание 😀\nВторая строка";
   v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);if(kind.equals("description"))m.openManagerFolder("QA_ROTATE_FOLDER");m.click(kind.equals("name")?"QA_ROTATE_POINT":"QA_ROTATE_NESTED");m.managerAction(kind.equals("name")?"Переименовать выбранное":"Изменить описание");m.inputs(text);m.runOnMainSync(()->{List<EditText> fields=new ArrayList<>();m.collectInputs(m.activeDialogRoot(),fields);fields.get(0).setSelection(3,8);});v.keyboard();m.check(editorMatches(text),"pre-rotation text/cursor fixture");if(outcome.equals("cancel"))v.snapshot("rotation-"+kind+"-before",true);
   if(outcome.equals("stale-before"))externalChange(store,id,true);byte[] expectedCurrent=xml(load(store,id));
   rotate(UiAutomation.ROTATION_FREEZE_90,text,"rotation-"+kind+"-"+outcome);m.check(m.activity.getIntent().getLongExtra("project",-1)==id,"project identity retained");Object draft=m.managerField("editorDraft");m.check(draft.getClass().getField("project").getLong(draft)==id&&token.equals(draft.getClass().getField("token").get(draft))&&key.equals(draft.getClass().getField("key").get(draft)),"original project/token/XML address retained");m.check(Arrays.equals(expectedCurrent,xml(load(store,id))),"recreation never writes XML");sameAssets(load(store,id),assets);
   if(outcome.equals("stale-before")){m.check(!saveEnabled(),"shifted XML address disables stale Save");m.check(m.managerKeys("selected").isEmpty(),"no selection rebound to shifted object");v.cancel();m.check(Arrays.equals(expectedCurrent,xml(load(store,id))),"stale Cancel preserves newer XML");}
   else{
    m.check(saveEnabled(),"unchanged project enables explicit Save");m.check(m.managerKeys("selected").equals(Arrays.asList(key)),"exact selected object restored");
    if(outcome.equals("cancel")){rotate(UiAutomation.ROTATION_FREEZE_0,text,"rotation-"+kind+"-return");v.cancel();m.check(Arrays.equals(before,xml(load(store,id))),"Cancel after two recreations retains original KML");}
    else if(outcome.equals("save")){Object expected=parse(before);m.staticCall(kind.equals("name")?"ObjectTree":"ObjectDescription",kind.equals("name")?"rename":"apply",new Class[]{Element.class,String.class,String.class,String.class},m.call(expected,"root",new Class[]{}),key,token,text);m.click("Сохранить");m.geometryReady();m.waitText("Изменения сохранены");Object actual=load(store,id);m.check(m.treeToken(expected).equals(m.treeToken(actual)),"explicit Save changes only target property, preserving all remaining XML");m.check(kind.equals("name")?m.element(actual,"point").getElementsByTagNameNS("*","name").item(0).getTextContent().equals(text):m.sourceDescription(actual,key).equals(text),"explicit Save updates original selected object");}
    else{externalChange(store,id,false);byte[] newer=xml(load(store,id));m.click("Сохранить");m.geometryReady();m.waitText("Проект изменился");v.snapshot("rotation-"+kind+"-rejected",false);m.click("Понятно");m.check(editorMatches(text),"stale Save failure retains text and cursor");m.click("Отмена");m.check(Arrays.equals(newer,xml(load(store,id))),"transaction rejects stale Save after restoration");}
   }
   sameAssets(load(store,id),assets);v.emit("ROTATION_RESULT kind="+kind+" outcome="+outcome+" PASS");
  }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}
 }
 void selectionScenario(Object store)throws Exception{
  Object doc=parse(XML.getBytes("UTF-8"));m.staticCall("MediaLinks","add",new Class[]{m.codec,Element.class,String.class,String.class,byte[].class},doc,m.element(doc,"nested"),"selection.jpg","image/jpeg",new byte[]{2,4,6,8});long id=(Long)m.call(store,"insert",new Class[]{m.codec,String.class},doc,"QA_SELECTION_ROTATION");
  try{doc=load(store,id);byte[] before=xml(doc);Map<String,byte[]> assets=new HashMap<>(m.assets(doc));v.finish();m.getUiAutomation().setRotation(UiAutomation.ROTATION_FREEZE_0);v.launch(id);v.rotate(UiAutomation.ROTATION_FREEZE_0);m.click("QA_ROTATE_POINT");m.openManagerFolder("QA_ROTATE_FOLDER");m.click("QA_ROTATE_NESTED");Set<String> chosen=new HashSet<>(Arrays.asList("1","0/0"));m.check(new HashSet<>(m.managerKeys("selected")).equals(chosen),"normal visible/hidden multiple selection fixture");Activity old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_90);m.check(m.activity!=old&&old.isDestroyed(),"normal manager actually recreated");m.check(new HashSet<>(m.managerKeys("selected")).equals(chosen),"normal visible and hidden selection restored");m.check("0".equals(m.managerField("folder"))&&m.visibleText("QA_ROTATE_NESTED"),"folder and visible child retained");v.controlReachable("Действия");v.controlReachable("Закрыть");v.controlReachable("Проекты, импорт и экспорт");v.snapshot("rotation-selection-restored",false);m.check(Arrays.equals(before,xml(load(store,id))),"normal selection recreation writes no XML");sameAssets(load(store,id),assets);
   externalChange(store,id,true);byte[] changed=xml(load(store,id));old=m.activity;v.rotate(UiAutomation.ROTATION_FREEZE_0);m.check(m.activity!=old&&old.isDestroyed(),"stale normal manager actually recreated");m.check(m.managerKeys("selected").isEmpty(),"changed XML clears whole selection, never rebinds old indices");m.check("".equals(m.managerField("folder")),"stale folder state resets to root");v.snapshot("rotation-selection-stale",false);m.check(Arrays.equals(changed,xml(load(store,id))),"invalidating stale selection preserves changed XML");sameAssets(load(store,id),assets);v.emit("ROTATION_RESULT normal-selection PASS");
  }finally{v.finish();m.call(store,"remove",new Class[]{long.class},id);}
 }
 void run()throws Exception{
  Context c=m.getTargetContext();m.installTileFixture();int network=m.requests.get();Object store=m.storeClass.getConstructor(Context.class).newInstance(c);AccessibilityServiceInfo service=m.getUiAutomation().getServiceInfo();int flags=service.flags;service.flags|=AccessibilityServiceInfo.FLAG_RETRIEVE_INTERACTIVE_WINDOWS;m.getUiAutomation().setServiceInfo(service);String keyboard=v.shell("settings get secure show_ime_with_hard_keyboard").trim();
  try{v.shell("settings put secure show_ime_with_hard_keyboard 1");for(String kind:new String[]{"name","description"})for(String outcome:new String[]{"cancel","save","stale-before","stale-after"})scenario(store,kind,outcome);selectionScenario(store);m.check(m.requests.get()==network,"manager rotation/editing issues no tile requests");}
  finally{v.finish();service.flags=flags;m.getUiAutomation().setServiceInfo(service);m.getUiAutomation().setRotation(UiAutomation.ROTATION_UNFREEZE);v.shell(keyboard.equals("null")?"settings delete secure show_ime_with_hard_keyboard":"settings put secure show_ime_with_hard_keyboard "+keyboard);m.call(store,"close",new Class[]{});}
 }
}
